command:
let hero = game.user.character;

if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled?.find(t => t.actor?.system?.class?.parent?.name?.toUpperCase() === "SORCERER")?.actor;
}

if (!hero) {
  ui.notifications.warn(`No Hero selected.`);
  return
}

const name = hero.system.parent.name;
const tap = hero.effects.find(fx => fx.name.toUpperCase() === "TAP");
if (!tap) return

// Reset HP
await tap.update({ "changes": [], "disabled": true })
await hero.update({
  "system.health.value": hero.system.health.max,
  "system.mana.value": hero.system.mana.max
});

ChatMessage.create({
  user: game.user._id,
  speaker: ChatMessage.getSpeaker({ token: hero }),
  content: `${name}: (Tap) Resetting max HP / Mana`
});
